def config_value(text: str, key: str) -> str:
    """Return the value for `key` in a `name=value` per-line config text.

    Each line is split at its first "=": the part before is the name and the
    part after is the value, with surrounding whitespace stripped from both.
    Values may themselves contain "=". Key matching is exact and
    case-sensitive.

    Blank lines, lines starting with "#" (after stripping), and lines without
    "=" are ignored. If the key appears more than once, the first occurrence
    wins. If the key is absent, return "". An existing key with an empty
    value also yields "". The function only inspects `text`; it never reads
    files.
    """
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    text = "host=localhost\nport=8080\nmode=fast"
    assert config_value(text, "host") == "localhost"
    assert config_value(text, "port") == "8080"
    assert config_value(text, "mode") == "fast"


def test_absent_key_returns_empty_string() -> None:
    assert config_value("a=1\nb=2", "c") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_is_stripped() -> None:
    assert config_value("  name  =  some value  \n", "name") == "some value"


def test_value_containing_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comments_and_blank_lines_ignored() -> None:
    text = "# a=commented\n\n   \n  # a=also commented\na=real"
    assert config_value(text, "a") == "real"


def test_commented_out_key_is_absent() -> None:
    assert config_value("#a=1", "a") == ""


def test_lines_without_equals_ignored() -> None:
    assert config_value("garbage\na=1\nmore garbage", "a") == "1"
    assert config_value("garbage", "garbage") == ""


def test_duplicate_key_first_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_key_match_is_exact_and_case_sensitive() -> None:
    text = "Name=upper\nname_x=other\nxname=prefix"
    assert config_value(text, "name") == ""
    assert config_value(text, "Name") == "upper"
    assert config_value(text, "name_x") == "other"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_key_in_value_not_matched() -> None:
    assert config_value("a=b=c", "b") == ""
    assert config_value("a=b=c", "a") == "b=c"


def test_no_trailing_newline_last_line() -> None:
    assert config_value("a=1\nlast=end", "last") == "end"
